div.script:
(function () {
    var carta = document.getElementById("carta-colombia");
    if (!carta) { return; }
    // La direccion de la carta. Si cambia (por ejemplo al pasarla a libertario-carta.pages.dev), solo se cambia esta linea.
    var CARTA = "https://menucolombia.libertario-carta.pages.dev/";

    // La ciudad o la sede del enlace o del QR pasan a la carta: /carta-colombia?ciudad=medellin abre la de Medellin.
    var paso = [];
    try {
        var pedido = new URLSearchParams(window.location.search);
        ["ciudad", "sede", "lang"].forEach(function (clave) {
            var valor = pedido.get(clave);
            if (valor) { paso.push(clave + "=" + encodeURIComponent(valor)); }
        });
    } catch (error) { /* un navegador viejo: la carta detecta la ciudad sola */ }
    carta.src = CARTA + (paso.length ? "?" + paso.join("&") : "");

    // En computador la carta mide exactamente lo que queda de ventana debajo del encabezado del sitio.
    var ancho = window.matchMedia("(min-width: 1024px)");
    function ajustar() {
        if (ancho.matches) {
            var arriba = carta.getBoundingClientRect().top;
            carta.style.height = Math.max(320, window.innerHeight - arriba) + "px";
        } else {
            carta.style.height = "";
        }
    }
    ajustar();
    window.addEventListener("resize", ajustar);
    window.addEventListener("load", ajustar);
    setTimeout(ajustar, 600);
})();
